// Every command is answered natively: Swift on the iPhone (ios/Sources/LacticPhonePlugin.swift),
// Kotlin on Android (android/src/main/java/LacticPhonePlugin.kt). This list gives each one its
// permission (permissions/autogenerated). The ble_* commands are Android's: there btleplug can't
// run, so the plugin does Bluetooth (the iPhone uses the core's ble.rs).
const COMMANDS: &[&str] = &[
    "status",
    "authorize_health",
    "read_health",
    "take_pending",
    "ack_pending",
    "save_workout",
    "pair",
    "unpair",
    "send",
    "schedule_ride_end",
    "cancel_ride_end",
    "ble_available",
    "ble_scan",
    "ble_stop_scan",
    "ble_connect",
    "ble_disconnect",
    "ble_subscribe",
    "ble_write",
    "ble_read",
    "register_listener",
    "remove_listener",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS).ios_path("ios").android_path("android").build();
}
